mapper.delete:
DELETE FROM fm_ai_analysis
 WHERE OID = #{oid,jdbcType=CHAR}
   AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}

mapper.select:
SELECT COALESCE(MAX(GENERATION_NO), 0) + 1
  FROM fm_ai_analysis
 WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
   AND CONTENT_HASH = #{contentHash,jdbcType=CHAR}

mapper.update:
UPDATE fm_ai_analysis
   SET EXECUTION_STATUS = 'SUCCEEDED', ERROR_CODE = NULL,
       COMPLETE_DATE = #{completeDate,jdbcType=TIMESTAMP},
       ELAPSED_MILLIS = #{elapsedMillis,jdbcType=BIGINT},
       INPUT_TOKENS = #{inputTokens,jdbcType=INTEGER},
       OUTPUT_TOKENS = #{outputTokens,jdbcType=INTEGER},
       RESULT_CONTENT = #{resultContent,jdbcType=LONGVARCHAR}
 WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
   AND ANALYSIS_ID = #{analysisId,jdbcType=VARCHAR}
   AND EXECUTION_STATUS IN ('PENDING', 'RUNNING')

UPDATE fm_ai_analysis
   SET EXECUTION_STATUS = 'FAILED', ERROR_CODE = #{errorCode,jdbcType=VARCHAR},
       COMPLETE_DATE = #{completeDate,jdbcType=TIMESTAMP},
       ELAPSED_MILLIS = #{elapsedMillis,jdbcType=BIGINT}
 WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
   AND ANALYSIS_ID = #{analysisId,jdbcType=VARCHAR}
   AND EXECUTION_STATUS IN ('PENDING', 'RUNNING')
